"""Replay the worker's real cancellation mirror after consent has changed."""
from contextlib import nullcontext
from copy import deepcopy
import json
from pathlib import Path
from types import SimpleNamespace
from unittest.mock import patch, Mock

from django.test import SimpleTestCase

from . import service_views as views
from . import website_connections as authority
from .website_contract import WebsiteAuthorityError


class CancellationReceiptTests(SimpleTestCase):
    def setUp(self):
        # Generated by CF harness/artifacts.py MlaiRunMirror._status_payload.
        self.payload = json.loads((Path(__file__).parent / "test_fixtures/cf_cancel_previous_connection.json").read_text())
        self.run = SimpleNamespace(run_id=self.payload["run_id"], domain=self.payload["domain"], workflow="article_system_setup",
            github_repo="fixtures/tala-old", status="running", current_step="revision_preview_building", error="", resume_available=True,
            run_request=deepcopy(self.payload["run_request"]), result={"saved_proof": {"source_sha": "original"}}, save=Mock())

    def put(self, payload, *, run=True):
        with patch.object(authority.transaction, "atomic", side_effect=lambda *a, **kw: nullcontext()), \
                patch.object(views.ContentFactoryRun.objects, "select_for_update") as rows, \
                patch.object(views.ContentFactoryRun.objects, "filter") as selected, \
                patch.object(views, "_serialize_content_factory_run", side_effect=lambda saved: {"run_id": saved.run_id, "status": saved.status}), \
                patch("content_factory.website_operations.observe_workflow_status"), \
                patch.object(authority, "authority_guard", side_effect=WebsiteAuthorityError("website_connection_required", "Reconnect this website.")) as grant, \
                patch.object(authority, "record_scan_evidence") as scan, \
                patch.object(views, "_apply_run_snapshot") as generic:
            rows.return_value.filter.return_value.first.return_value = self.run if run else None
            selected.return_value.first.return_value = self.run if run else None
            request = SimpleNamespace(method="PUT", data=payload)
            response = views.ContentFactoryRunView().put(request, run_id=self.payload["run_id"])
        return response, grant, scan, generic

    def test_exact_cf_previous_generation_payload_is_a_pure_cancel(self):
        before = deepcopy(self.run.run_request)
        response, grant, scan, generic = self.put(self.payload)
        self.assertEqual(response.status_code, 200, response.data)
        self.assertEqual(self.run.status, "cancelled")
        self.assertEqual(self.run.current_step, "cancelled")
        self.assertFalse(self.run.resume_available)
        self.assertEqual(self.run.run_request, before)
        self.assertEqual(self.run.result["saved_proof"], {"source_sha": "original"})
        grant.assert_not_called()
        scan.assert_not_called()
        generic.assert_not_called()

    def test_portable_and_missing_connection_cancel_receipts_are_accepted(self):
        for mode in (None, "content_only"):
            with self.subTest(mode=mode):
                payload = {"status": "cancelled", "domain": self.run.domain, "run_request": {"delivery_mode": mode}}
                self.assertEqual(self.put(payload)[0].status_code, 200)

    def test_repository_configuration_and_tokens_are_discarded(self):
        payload = {**self.payload, "publish_targets": [{"key": "claimed"}], "github_token": "synthetic-secret",
            "github_repo": "fixtures/claimed", "article_system": {"ready": True}, "result": {
                "cancelled": True, "cleanup": {"remote_cleanup_pending": True, "github_token": "synthetic-secret", "repository_id": 999},
                "article_system_setup": {"status": "completed"}}}
        response, grant, scan, generic = self.put(payload)
        self.assertEqual(response.status_code, 200)
        self.assertEqual(self.run.github_repo, "fixtures/tala-old")
        self.assertNotIn("synthetic-secret", json.dumps(self.run.result))
        self.assertNotIn("article_system_setup", self.run.result)
        self.assertNotIn("repository_id", self.run.result["cleanup"])
        self.assertTrue(self.run.result["cleanup"]["remote_cleanup_pending"])

    def test_unknown_run_and_wrong_domain_fail_closed(self):
        self.assertEqual(self.put(self.payload, run=False)[0].status_code, 404)
        for payload in ({**self.payload, "domain": "other.test"}, {**self.payload, "run_request": {"domain": "other.test"}}):
            with self.subTest(payload=payload):
                self.assertEqual(self.put(payload)[0].status_code, 409)
        self.run.save.assert_not_called()
